package com.vision.iptv;
import android.app.*; import android.os.*; import android.view.*; import android.widget.*; import androidx.media3.common.MediaItem; import androidx.media3.exoplayer.ExoPlayer; import androidx.media3.ui.PlayerView; import java.util.*; import java.net.*; import java.io.*;
public class MainActivity extends Activity {
 static class Channel {String name,url,group; Channel(String n,String u,String g){name=n;url=u;group=g;}}
 final ArrayList<Channel> channels=new ArrayList<>(); final Set<String> favorites=new HashSet<>(); LinearLayout list, sidebar; PlayerView video; ExoPlayer player; TextView status; String filter="", group=""; boolean onlyFav=false; Channel current; boolean fullscreen=false; android.content.SharedPreferences prefs;
 @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().addFlags(128); prefs=getSharedPreferences("vision",0); favorites.addAll(prefs.getStringSet("favorites",Collections.emptySet())); LinearLayout root=new LinearLayout(this); root.setOrientation(0); root.setBackgroundColor(0xff101722); sidebar=new LinearLayout(this); sidebar.setOrientation(1); root.addView(sidebar,new LinearLayout.LayoutParams(dp(330),-1)); LinearLayout right=new LinearLayout(this); right.setOrientation(1); root.addView(right,new LinearLayout.LayoutParams(0,-1,1)); TextView title=new TextView(this); title.setText("VISION IPTV PRO"); title.setTextSize(22); title.setPadding(16,16,16,16); sidebar.addView(title); button(sidebar,"Добавить M3U",()->add()); button(sidebar,"Все каналы / Избранное",()->{onlyFav=!onlyFav;render();}); button(sidebar,"Полный экран",()->toggleFullscreen()); button(sidebar,"Группы",()->groups()); button(sidebar,"Поиск",()->search()); button(sidebar,"В избранное / удалить",()->{if(current!=null){if(!favorites.add(current.url))favorites.remove(current.url);prefs.edit().putStringSet("favorites",new HashSet<>(favorites)).apply();render();}}); ScrollView scroll=new ScrollView(this); list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);sidebar.addView(scroll,new LinearLayout.LayoutParams(-1,0,1)); video=new PlayerView(this);right.addView(video,new LinearLayout.LayoutParams(-1,0,1));status=new TextView(this);status.setText("Добавьте свой IPTV-плейлист");status.setPadding(16,12,16,12);right.addView(status);setContentView(root); player=new ExoPlayer.Builder(this).build();video.setPlayer(player);player.addListener(new androidx.media3.common.Player.Listener(){@Override public void onPlayerError(androidx.media3.common.PlaybackException error){status.setText("Ошибка воспроизведения: "+error.getErrorCodeName());Toast.makeText(MainActivity.this,"Не удалось воспроизвести канал",Toast.LENGTH_SHORT).show();}});parse(prefs.getString("playlist",""));render(); }
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 void button(LinearLayout parent,String name,Runnable action){Button b=new Button(this);b.setText(name);b.setAllCaps(false);b.setTextSize(14);b.setFocusable(true);b.setOnClickListener(v->action.run());parent.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 void add(){EditText e=new EditText(this);e.setSingleLine();e.setHint("https://.../playlist.m3u");new AlertDialog.Builder(this).setTitle("Адрес плейлиста").setView(e).setPositiveButton("Загрузить",(d,w)->load(e.getText().toString().trim())).setNegativeButton("Отмена",null).show();}
 void load(String url){status.setText("Загрузка…");new Thread(()->{try{URL u=new URL(url);if(!u.getProtocol().equals("https")&&!u.getProtocol().equals("http"))throw new IOException("HTTP(S) only");URLConnection c=u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);StringBuilder s=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream(),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){s.append(line).append('\n');if(s.length()>20000000)throw new IOException("Playlist too large");}}String data=s.toString();runOnUiThread(()->{if(!data.contains("#EXTINF")){status.setText("Не найден список каналов M3U");return;}prefs.edit().putString("playlist",data).apply();parse(data);render();status.setText("Каналов: "+channels.size());});}catch(Exception ex){runOnUiThread(()->status.setText("Ошибка загрузки плейлиста"));}}).start();}
 void parse(String data){channels.clear();String name="",g="";for(String raw:data.split("\\r?\\n")){String l=raw.trim();if(l.startsWith("#EXTINF")){int comma=l.indexOf(',');name=comma>=0?l.substring(comma+1):"Канал";java.util.regex.Matcher m=java.util.regex.Pattern.compile("group-title=\"([^\"]*)\"").matcher(l);g=m.find()?m.group(1):"Без группы";}else if(l.startsWith("http://")||l.startsWith("https://")){channels.add(new Channel(name.isEmpty()?l:name,l,g));name="";g="";}}}
 void render(){list.removeAllViews();for(Channel c:channels){if(onlyFav&&!favorites.contains(c.url)||!group.isEmpty()&&!group.equals(c.group)||!c.name.toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT)))continue;button(list,(favorites.contains(c.url)?"★ ":"")+c.name,()->play(c));}}
 void play(Channel c){current=c;status.setText(c.name);player.setMediaItem(MediaItem.fromUri(c.url));player.prepare();player.play();video.requestFocus();}
 void groups(){TreeSet<String> gs=new TreeSet<>();for(Channel c:channels)gs.add(c.group);ArrayList<String> a=new ArrayList<>();a.add("Все группы");a.addAll(gs);new AlertDialog.Builder(this).setTitle("Группы").setItems(a.toArray(new String[0]),(d,i)->{group=i==0?"":a.get(i);render();}).show();}
 void search(){EditText e=new EditText(this);e.setText(filter);new AlertDialog.Builder(this).setTitle("Поиск каналов").setView(e).setPositiveButton("Найти",(d,w)->{filter=e.getText().toString();render();}).setNegativeButton("Сбросить",(d,w)->{filter="";render();}).show();}
 void toggleFullscreen(){fullscreen=!fullscreen;sidebar.setVisibility(fullscreen?View.GONE:View.VISIBLE);status.setVisibility(fullscreen?View.GONE:View.VISIBLE);getWindow().getDecorView().setSystemUiVisibility(fullscreen?5894:0);if(fullscreen)video.requestFocus();else sidebar.requestFocus();}
 void stepChannel(int direction){if(channels.isEmpty())return;ArrayList<Channel> visible=new ArrayList<>();for(Channel c:channels){if(onlyFav&&!favorites.contains(c.url)||!group.isEmpty()&&!group.equals(c.group)||!c.name.toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT)))continue;visible.add(c);}if(visible.isEmpty())return;int i=visible.indexOf(current);play(visible.get(i<0?0:(i+direction+visible.size())%visible.size()));}
 @Override public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_CHANNEL_UP){stepChannel(1);return true;}if(key==KeyEvent.KEYCODE_CHANNEL_DOWN){stepChannel(-1);return true;}if(key==KeyEvent.KEYCODE_MENU){toggleFullscreen();return true;}if(key==KeyEvent.KEYCODE_BACK&&fullscreen){toggleFullscreen();return true;}return super.onKeyDown(key,event);}
 @Override protected void onStop(){super.onStop();if(player!=null)player.pause();} @Override protected void onDestroy(){if(player!=null)player.release();super.onDestroy();}
}